<script setup>
/**
 * StudySummary — key-point summary of a note, generated by Gemini (aiService).
 * No rule-based fallback: if AI is disabled it shows a notice.
 */
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { summarize } from '../../services/aiService.js'
import { cachedGenerate } from '../../services/studySetCacheService.js'
import { useAuthStore } from '../../stores/authStore.js'

const { t } = useI18n()
const auth = useAuthStore()
const props = defineProps({
  content: { type: String, default: '' },
  maxSentences: { type: Number, default: 4 },
  // When set (e.g. `note:<id>`), the summary is cached per user and reused
  // instead of costing an AI call on every open. Empty string disables caching.
  cacheKey: { type: String, default: '' }
})

const summary = ref([])
const loading = ref(false)
const failed = ref(false)

async function run() {
  failed.value = false
  if (!props.content) { summary.value = []; return }
  loading.value = true
  try {
    const { data } = await cachedGenerate({
      userId: auth.user?.id,
      kind: 'summary',
      sourceKey: props.cacheKey,
      content: props.content,
      options: { max: props.maxSentences },
      generator: (c, o) => summarize(c, o)
    })
    summary.value = data || []
  } catch {
    failed.value = true
    summary.value = []
  } finally {
    loading.value = false
  }
}

watch(() => props.content, run, { immediate: true })
</script>

<template>
  <div class="panel">
    <div class="section-title"><i class="bi bi-card-list"></i>{{ t('editor.summaryTitle') }}</div>

    <p v-if="loading" class="tool-empty"><i class="bi bi-arrow-repeat spin"></i> {{ t('ai.generating') }}</p>
    <p v-else-if="failed" class="tool-empty">{{ t('ai.failed') }}</p>
    <p v-else-if="!summary.length" class="tool-empty">{{ t('editor.summaryEmpty') }}</p>

    <ol v-else class="summary-list">
      <li v-for="(sentence, i) in summary" :key="i">{{ sentence }}</li>
    </ol>
  </div>
</template>
